tool_input.command:
cat > /tmp/test-thresholds.mjs << 'EOF'
import { execSync } from 'child_process';
import fs from 'fs';
import path from 'path';
import os from 'os';

const projectRoot = '/private/tmp/100-tricks-runs/d50/with/h2-eval-thresholds/r2';
const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-test-'));

try {
  // Create test data
  const outputs = ['hello', 'world', 'test'];
  const references = ['hello', 'world', 'test'];

  const outputsFile = path.join(tmpDir, 'outputs.json');
  const referencesFile = path.join(tmpDir, 'references.json');
  const reportFile = path.join(tmpDir, 'report.json');

  fs.writeFileSync(outputsFile, JSON.stringify(outputs));
  fs.writeFileSync(referencesFile, JSON.stringify(references));

  console.log('Test 1: Passing threshold');
  try {
    execSync(`cd ${projectRoot} && node packages/frai-cli/dist/index.js eval --outputs ${outputsFile} --references ${referencesFile} --report ${reportFile} --threshold exact_match=0.5`, {
      stdio: 'inherit'
    });
    console.log('✓ Test 1 passed (exit code 0)');
  } catch (e) {
    console.log('✗ Test 1 failed with exit code:', e.status);
  }

  console.log('\nTest 2: Failing threshold');
  try {
    execSync(`cd ${projectRoot} && node packages/frai-cli/dist/index.js eval --outputs ${outputsFile} --references ${referencesFile} --report ${reportFile} --threshold exact_match=0.95`, {
      stdio: 'inherit'
    });
    console.log('✗ Test 2 failed (should have exited with code 1)');
  } catch (e) {
    if (e.status === 1) {
      console.log('✓ Test 2 passed (exit code 1)');
    } else {
      console.log('✗ Test 2 failed with exit code:', e.status);
    }
  }

  console.log('\nTest 3: Invalid threshold format');
  try {
    execSync(`cd ${projectRoot} && node packages/frai-cli/dist/index.js eval --outputs ${outputsFile} --references ${referencesFile} --report ${reportFile} --threshold invalid`, {
      stdio: 'inherit'
    });
    console.log('✗ Test 3 failed (should have exited with code 2)');
  } catch (e) {
    if (e.status === 2) {
      console.log('✓ Test 3 passed (exit code 2)');
    } else {
      console.log('✗ Test 3 failed with exit code:', e.status);
    }
  }

  console.log('\nTest 4: Check report contents');
  const reportContent = JSON.parse(fs.readFileSync(reportFile, 'utf8'));
  if (reportContent.thresholds && reportContent.passed !== undefined) {
    console.log('✓ Test 4 passed (report contains thresholds and passed field)');
  } else {
    console.log('✗ Test 4 failed (report missing thresholds or passed field)');
  }

} finally {
  fs.rmSync(tmpDir, { recursive: true, force: true });
}
EOF
node /tmp/test-thresholds.mjs
